import os
import re
import unicodedata
from pathlib import PurePosixPath
from flask import Flask, request, jsonify, send_file, abort
import hashlib
import hmac
import time

app = Flask(__name__)

UPLOAD_ROOT = '/var/app/uploads'
ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.png', '.jpg', '.gif', '.doc', '.docx'}
MAX_FILENAME_LEN = 255
API_SECRET = os.environ.get('API_SECRET', '')

def constant_time_compare(a, b):
    return hmac.compare_digest(a.encode(), b.encode())

def verify_request_signature(req):
    """Verify HMAC signature on request to prevent unauthorized access."""
    sig = req.headers.get('X-Signature', '')
    timestamp = req.headers.get('X-Timestamp', '')
    if not sig or not timestamp:
        return False
    try:
        ts = int(timestamp)
        if abs(time.time() - ts) > 300:
            return False
    except ValueError:
        return False
    payload = f"{req.method}:{req.path}:{timestamp}"
    expected = hmac.new(API_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return constant_time_compare(sig, expected)

def sanitize_filename(filename):
    """Multi-layer filename sanitization."""
    # Step 1: Strip null bytes
    filename = filename.replace('\x00', '')

    # Step 2: Unicode NFC normalization
    filename = unicodedata.normalize('NFC', filename)

    # Step 3: Validate against path traversal patterns
    if re.search(r'\.\.|\.\./', filename):
        return None

    # Step 4: Resolve any remaining path components
    # Use PurePosixPath to normalize
    path = PurePosixPath(filename)
    clean_name = path.name  # Get just the filename part

    # Step 5: Check extension
    _, ext = os.path.splitext(clean_name)
    if ext.lower() not in ALLOWED_EXTENSIONS:
        return None

    # Step 6: Length check
    if len(clean_name) > MAX_FILENAME_LEN:
        return None

    return clean_name

def resolve_user_path(user_id, filename):
    """Resolve the full path for a user's file."""
    # Sanitize user_id - alphanumeric only
    if not re.match(r'^[a-zA-Z0-9_-]+$', user_id):
        return None

    # Build the path
    user_dir = os.path.join(UPLOAD_ROOT, user_id)

    # NFKC normalization for filesystem compatibility
    normalized_filename = unicodedata.normalize('NFKC', filename)

    full_path = os.path.join(user_dir, normalized_filename)

    # Verify the resolved path is within bounds
    real_path = os.path.realpath(full_path)
    real_root = os.path.realpath(user_dir)

    if not real_path.startswith(real_root + os.sep) and real_path != real_root:
        return None

    return full_path

@app.route('/api/files/<user_id>', methods=['GET'])
def list_files(user_id):
    """List files for a user."""
    if not re.match(r'^[a-zA-Z0-9_-]+$', user_id):
        abort(400)

    user_dir = os.path.join(UPLOAD_ROOT, user_id)
    if not os.path.isdir(user_dir):
        return jsonify({'files': []})

    files = []
    for f in os.listdir(user_dir):
        fpath = os.path.join(user_dir, f)
        if os.path.isfile(fpath):
            files.append({'name': f, 'size': os.path.getsize(fpath)})

    return jsonify({'files': files})

@app.route('/api/files/<user_id>/<path:filename>', methods=['GET'])
def download_file(user_id, filename):
    """Download a specific file."""
    # Sanitize the filename
    clean_name = sanitize_filename(filename)
    if clean_name is None:
        abort(400)

    # Resolve path
    file_path = resolve_user_path(user_id, clean_name)
    if file_path is None:
        abort(403)

    if not os.path.isfile(file_path):
        abort(404)

    return send_file(file_path)

@app.route('/api/files/<user_id>/upload', methods=['POST'])
def upload_file(user_id):
    """Upload a file for a user."""
    if not re.match(r'^[a-zA-Z0-9_-]+$', user_id):
        abort(400)

    if 'file' not in request.files:
        abort(400)

    uploaded = request.files['file']
    if not uploaded.filename:
        abort(400)

    clean_name = sanitize_filename(uploaded.filename)
    if clean_name is None:
        abort(400)

    file_path = resolve_user_path(user_id, clean_name)
    if file_path is None:
        abort(403)

    # Ensure directory exists
    user_dir = os.path.join(UPLOAD_ROOT, user_id)
    os.makedirs(user_dir, exist_ok=True)

    uploaded.save(file_path)
    return jsonify({'status': 'ok', 'filename': clean_name}), 201

@app.route('/api/shared/<share_token>', methods=['GET'])
def download_shared(share_token):
    """Download a shared file using a share token.
    Token format: base64(user_id:filename:expiry):signature
    """
    import base64

    parts = share_token.rsplit(':', 1)
    if len(parts) != 2:
        abort(400)

    encoded_payload, signature = parts

    # Verify signature
    expected_sig = hmac.new(
        API_SECRET.encode(), encoded_payload.encode(), hashlib.sha256
    ).hexdigest()[:16]

    if not constant_time_compare(signature, expected_sig):
        abort(403)

    try:
        payload = base64.b64decode(encoded_payload).decode('utf-8')
    except Exception:
        abort(400)

    payload_parts = payload.split(':', 2)
    if len(payload_parts) != 3:
        abort(400)

    user_id, filename, expiry = payload_parts

    try:
        if time.time() > float(expiry):
            abort(410)
    except ValueError:
        abort(400)

    # Use the filename directly from the signed payload - it was validated at share creation time
    file_path = resolve_user_path(user_id, filename)
    if file_path is None:
        abort(403)

    if not os.path.isfile(file_path):
        abort(404)

    return send_file(file_path)

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
